import jwt from"jsonwebtoken";import bcript from"bcrypt";let SECRET_KEY=process.env.JWT_SECRET;function gerarToken(r){r={id:r.id,email:r.email};return jwt.sign(r,SECRET_KEY,{expiresIn:"7d"})}function verificarToken(e,n,a){var r=e.headers.authorization,r=r&&r.split(" ")[1];if(!r)return n.status(401).json({erro:"Token não fornecido ou acesso negado."});jwt.verify(r,SECRET_KEY,(r,o)=>{if(r)return n.status(403).json({erro:"Token inválido ou expirado."});e.usuario=o,a()})}let saltRounds=10;async function criarHash(r){return bcrypt.hash(r,saltRounds)}async function compararSenha(r,o){return bcrypt.compare(r,o)}export{gerarToken,verificarToken,criarHash,compararSenha};